<div class="feature-grid" data-search-items>
<?php $__currentLoopData = $features; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $feature): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?>
<article class="feature-card" id="<?php echo e($feature['id']); ?>" data-search-item data-category="<?php echo e($feature['category']); ?>" data-reveal><div class="feature-card-top"><span class="feature-icon icon-<?php echo e($loop->index); ?>"><?php echo $__env->make('public.partials.icon', ['icon' => $feature['icon']], array_diff_key(get_defined_vars(), ['__data' => 1, '__path' => 1]))->render(); ?></span><span class="card-label"><?php echo e($feature['category']); ?></span></div><h3><?php echo e($feature['title']); ?></h3><p><?php echo e($feature['description']); ?></p><?php if($detailed ?? false): ?><ul class="detail-list"><?php $__currentLoopData = $feature['details']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $detail): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><li><?php echo $__env->make('public.partials.icon', ['icon' => 'check'], array_diff_key(get_defined_vars(), ['__data' => 1, '__path' => 1]))->render(); ?><?php echo e($detail); ?></li><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></ul><div class="use-case"><span>IN PRACTICE</span><p><?php echo e($feature['use']); ?></p></div><?php else: ?><a class="text-link" href="<?php echo e(route('public.features')); ?>#<?php echo e($feature['id']); ?>">Explore <?php echo e(strtolower($feature['category'])); ?> <span aria-hidden="true">↗</span></a><?php endif; ?></article>
<?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?>
</div>
